-- 0056_portable_trigram: reference tables of the portable trigram engine
-- (ADR-0034): the `trigram` index kind and `fuzzy` search without pg_trgm.
--
-- SQLite has no lower() beyond ASCII and no way to split text into words in
-- a trigger, so the SQL that maintains a trigram index walks a value one
-- character at a time over a table of positions and reads how to treat each
-- non-ASCII character from a fold table:
--
-- * _forgebase_trgm_positions: the integers 1 to 4100 (forgebase-query
--   trigram::POSITIONS): the first 4096 characters of a value and, two
--   windows a row, the windows of its padded form;
-- * _forgebase_trgm_fold: (code point, lowercase code point) for the
--   non-ASCII characters of trigram::FOLD_BLOCKS that are not word
--   characters as they are; lower_cp = 0 separates words. Generated once
--   from Unicode data (crates/forgebase-query/src/trigram_fold.rs; a unit
--   test keeps both equal).
--
-- Each trigram index is a table _forgebase_trgm_<index> (rid, k, tri) kept
-- by triggers, created with the index (not here). PostgreSQL computes the
-- same trigrams with its own functions (postgres/0056); both backends get
-- both tables so the schemas stay identical.

CREATE TABLE _forgebase_trgm_positions (
    i INTEGER NOT NULL PRIMARY KEY
) STRICT, WITHOUT ROWID;

WITH RECURSIVE n(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM n WHERE i < 4100)

CREATE TABLE _forgebase_trgm_fold (
    cp       INTEGER NOT NULL PRIMARY KEY,
    lower_cp INTEGER NOT NULL
) STRICT, WITHOUT ROWID;

